package tr.kasaba.test;
import com.google.gson.*;import java.lang.reflect.*;import java.util.*;import java.nio.charset.StandardCharsets;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.plugin.java.JavaPlugin;
import tr.kasaba.hub.api.*;
/** Loopback-only adapter. Never distributed. */
public final class TacProbe extends JavaPlugin implements org.bukkit.plugin.messaging.PluginMessageListener {
 Object game;final Gson json=new GsonBuilder().serializeNulls().create();
 public void onEnable(){if(!Bukkit.getIp().equals("127.0.0.1"))throw new IllegalStateException("Loopback only");game=Bukkit.getPluginManager().getPlugin("KasabaTac");Bukkit.getMessenger().registerIncomingPluginChannel(this,"kasaba_test:tac",this);}
 public void onPluginMessageReceived(String channel,Player p,byte[] bytes){if(p.getAddress()==null||!p.getAddress().getAddress().isLoopbackAddress())return;String op=new String(bytes,StandardCharsets.UTF_8);Bukkit.getScheduler().runTask(this,()->{try{String[] a=op.split("\\|");Object room=((Map<?,?>)get(game,"membership")).get(p.getUniqueId());switch(a[0]){
 case "STATE"->{Map<String,Object>d=new LinkedHashMap<>();var hub=Bukkit.getServicesManager().load(HubApi.class);d.put("uuid",p.getUniqueId());d.put("world",p.getWorld().getName());d.put("location",List.of(p.getX(),p.getY(),p.getZ()));d.put("visitor",((Set<?>)get(game,"visitors")).contains(p.getUniqueId()));d.put("queued",((Set<?>)get(game,"queue")).contains(p.getUniqueId()));World template=Bukkit.getWorld((String)get(get(game,"map"),"worldName"));d.put("chain",template.getBlockAt(-43,83,-11).getType());World lobby=(World)get(game,"lobbyWorld");d.put("boards",lobby.getEntitiesByClass(TextDisplay.class).stream().filter(t->t.getScoreboardTags().contains("kasaba-board:lanetlitac/info")||t.getScoreboardTags().contains("kasaba-board:lanetlitac/top")).count());d.put("social",hub.socialArea(p.getUniqueId()));d.put("gameplay",hub.gameplay(p.getUniqueId()));d.put("rooms",((Map<?,?>)get(game,"rooms")).size());d.put("privateWorlds",Bukkit.getWorlds().stream().map(World::getName).filter(n->n.startsWith("tac_room_")).toList());d.put("items",Arrays.stream(p.getInventory().getContents()).map(i->i==null?"AIR":i.getType().name()+":"+i.getAmount()).toList());d.put("hp",p.getHealth());d.put("slow",p.hasPotionEffect(org.bukkit.potion.PotionEffectType.SLOWNESS));d.put("room",room==null?null:get(room,"id"));if(room!=null){d.put("phase",get(room,"phase"));d.put("practice",get(room,"practice"));d.put("crown",get(room,"crown"));d.put("scores",get(room,"scores"));d.put("glow",p.isGlowing());d.put("helmet",p.getInventory().getHelmet()==null?"AIR":p.getInventory().getHelmet().getType());d.put("northOpen",get(room,"northOpen"));d.put("eastOpen",get(room,"eastOpen"));d.put("bar",((org.bukkit.boss.BossBar)get(room,"bar")).getTitle());World w=(World)get(room,"world");d.put("northCell",w.getBlockAt(0,81,-17).getType());d.put("templateNorth",template.getBlockAt(0,81,-17).getType());}say(p,"state:"+json.toJson(d));}
 case "AGEQUEUE"->{set(game,"queueDeadline",System.currentTimeMillis()-1);call(game,"tick");}
 case "TIMEOUT"->{set(room,"startedAt",System.currentTimeMillis()-241000);call(room,"tick",System.currentTimeMillis());}
 case "END"->{set(room,"finishAt",System.currentTimeMillis()-1);call(room,"tick",System.currentTimeMillis());}
 case "AGE"->{set(room,"startedAt",System.currentTimeMillis()-Long.parseLong(a[1])*1000);call(room,"tick",System.currentTimeMillis());}
 case "NEAR"->{Player target=Bukkit.getPlayerExact(a[1]);call(game,"teleport",p,target.getLocation().clone().add(.7,0,0));}
 case "FAR"->{call(game,"teleport",p,new Location(p.getWorld(),11.5,81,11.5));}
 case "TOUCH"->{set(room,"lastTransfer",System.currentTimeMillis()-3000);call(room,"tick",System.currentTimeMillis());}
 case "POINTS"->{((Map<UUID,Integer>)get(room,"scores")).put(p.getUniqueId(),Integer.parseInt(a[1]));}
 case "GATE"->{set(room,"startedAt",System.currentTimeMillis()-Integer.parseInt(a[1])*30000L-1000);set(room,"gateStep",Integer.parseInt(a[1]));call(room,"rotateGates");}
 case "NORTH"->{call(game,"teleport",p,new Location(p.getWorld(),.5,81,-16.5));}
 case "INV_COMPASS"->{var view=p.getOpenInventory();int slot=-1;for(int i=0;i<view.countSlots();i++)if(view.getInventory(i)==p.getInventory()&&view.convertSlot(i)==8){slot=i;break;}var event=new org.bukkit.event.inventory.InventoryClickEvent(view,org.bukkit.event.inventory.InventoryType.SlotType.QUICKBAR,slot,org.bukkit.event.inventory.ClickType.RIGHT,org.bukkit.event.inventory.InventoryAction.PICKUP_HALF);Bukkit.getPluginManager().callEvent(event);}
 case "GUARDS"->{var breakEvent=new BlockBreakEvent(p.getLocation().clone().subtract(0,1,0).getBlock(),p);Bukkit.getPluginManager().callEvent(breakEvent);var damage=new EntityDamageEvent(p,EntityDamageEvent.DamageCause.FALL,5);Bukkit.getPluginManager().callEvent(damage);var gm=new PlayerGameModeChangeEvent(p,GameMode.CREATIVE);Bukkit.getPluginManager().callEvent(gm);var tp=new PlayerTeleportEvent(p,p.getLocation(),Bukkit.getWorlds().getFirst().getSpawnLocation());Bukkit.getPluginManager().callEvent(tp);var fly=new PlayerToggleFlightEvent(p,true);Bukkit.getPluginManager().callEvent(fly);var command=new PlayerCommandPreprocessEvent(p,"/give @s diamond");Bukkit.getPluginManager().callEvent(command);say(p,"guards:"+json.toJson(Map.of("break",breakEvent.isCancelled(),"damage",damage.isCancelled(),"mode",gm.isCancelled(),"teleport",tp.isCancelled(),"fly",fly.isCancelled(),"command",command.isCancelled())));}
 case "CLOSE_ALL"->{for(Object r:List.copyOf(((Map<?,?>)get(game,"rooms")).values()))call(r,"close");}
 default->throw new IllegalArgumentException(op);}
 say(p,"done:"+op);}catch(Throwable e){say(p,"error:"+e);getLogger().log(java.util.logging.Level.SEVERE,"Tac fixture",e);}});}
 Object get(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 void set(Object target,String name,Object value)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}
 Object call(Object target,String name,Object... args)throws Exception{Method m=Arrays.stream(target.getClass().getDeclaredMethods()).filter(x->x.getName().equals(name)&&x.getParameterCount()==args.length).findFirst().orElseThrow();m.setAccessible(true);return m.invoke(target,args);}
 void say(Player p,String text){p.sendMessage(net.kyori.adventure.text.Component.text("tac-probe:"+text));}
}
